# The layer's files and where each goes in the prepared tree (build/platform):
#   <layer file> <path in the tree> <add|replace>
# add: the pinned platform has no such path (an upstream file there stops the build);
# replace: the platform has it and ours takes its place (a missing one stops the build).
# tools/prepare.py fails when a file under pocket/translation, pocket/launcher or
# pocket/profiles is missing here, or an entry names a file that does not exist.
#
# The Steam library, in place of Valve's libsteam_api.dylib, and its bridge to the app's session
pocket/translation/libsteam_api/Steam.c translation/libsteam_api/Steam.c add
pocket/translation/libsteam_api/Steam.h translation/libsteam_api/Steam.h add
pocket/translation/libsteam_api/PocketSteamBridge.h translation/libsteam_api/PocketSteamBridge.h add
# The app's own Steam sign-in and session (called by pocket/patches/0005)
pocket/launcher/Pocket/PocketSteam.c launcher/Pocket/PocketSteam.c add
pocket/launcher/Pocket/PocketSteam.h launcher/Pocket/PocketSteam.h add
pocket/launcher/Pocket/PocketSteamClient.h launcher/Pocket/PocketSteamClient.h add
pocket/launcher/Pocket/PocketSteamClient.m launcher/Pocket/PocketSteamClient.m add
pocket/launcher/Pocket/PocketSteamLaunch.h launcher/Pocket/PocketSteamLaunch.h add
pocket/launcher/Pocket/PocketSteamLaunch.m launcher/Pocket/PocketSteamLaunch.m add
# Game updates on the device: Steam's build fetched from its content servers and put in place before the game starts (called by PocketSteamLaunch.m)
pocket/launcher/Pocket/PocketGameUpdates.h launcher/Pocket/PocketGameUpdates.h add
pocket/launcher/Pocket/PocketGameUpdates.m launcher/Pocket/PocketGameUpdates.m add
pocket/launcher/Pocket/PocketInstalledGame.h launcher/Pocket/PocketInstalledGame.h add
pocket/launcher/Pocket/PocketInstalledGame.m launcher/Pocket/PocketInstalledGame.m add
pocket/launcher/Pocket/PocketDepot.h launcher/Pocket/PocketDepot.h add
pocket/launcher/Pocket/PocketDepot.m launcher/Pocket/PocketDepot.m add
pocket/launcher/Pocket/PocketZstd.h launcher/Pocket/PocketZstd.h add
pocket/launcher/Pocket/PocketZstd.c launcher/Pocket/PocketZstd.c add
# ...and zstd's reference decoder, unchanged (BSD licence; included by PocketZstd.c)
pocket/launcher/Pocket/zstd/zstd_decompress.inc launcher/Pocket/zstd/zstd_decompress.inc add
pocket/launcher/Pocket/zstd/zstd_decompress.h launcher/Pocket/zstd/zstd_decompress.h add
pocket/launcher/Pocket/zstd/LICENSE launcher/Pocket/zstd/LICENSE add
# Local signing on the device: the page container for a new game build made and signed by the app itself (called by pocket/patches/0024)
pocket/launcher/Pocket/PocketLocalSigning.h launcher/Pocket/PocketLocalSigning.h add
pocket/launcher/Pocket/PocketLocalSigning.m launcher/Pocket/PocketLocalSigning.m add
# ...and the developer identity it signs with, given once from the Mac (run by pocket/patches/0024's tools/install.sh)
pocket/tools/give_signing_identity.sh tools/give_signing_identity.sh add
pocket/tools/export_signing_identity.m tools/export_signing_identity.m add
# The folder-walk guard in front of libSystem (the client's walk up from its folder, under the iOS sandbox)
pocket/translation/libSystem.B/ContainerPaths.c translation/libSystem.B/ContainerPaths.c add
pocket/translation/libSystem.B/ContainerPaths.h translation/libSystem.B/ContainerPaths.h add
# What the client asks of AppKit and QuartzCore beyond Tolkara's adapter
pocket/translation/AppKit/PocketCompat.m translation/AppKit/PocketCompat.m add
# The in-game settings: a button beside the on-screen controls, its sheet, the performance overlay (called by pocket/patches/0010)
pocket/translation/AppKit/PocketSettings.h translation/AppKit/PocketSettings.h add
pocket/translation/AppKit/PocketSettings.m translation/AppKit/PocketSettings.m add
# The loading screen while the game starts (made the launcher's status screen by pocket/patches/0027)
pocket/launcher/Pocket/PocketLoadingView.h launcher/Pocket/PocketLoadingView.h add
pocket/launcher/Pocket/PocketLoadingView.m launcher/Pocket/PocketLoadingView.m add
# The Steam sign-in's screens, a form sheet (presented by PocketSteamLaunch.m and PocketGameUpdates.m)
pocket/launcher/Pocket/PocketSignInViewController.h launcher/Pocket/PocketSignInViewController.h add
pocket/launcher/Pocket/PocketSignInViewController.m launcher/Pocket/PocketSignInViewController.m add
# AIR 1.x Metal libraries for the on-device rewrap (used by pocket/patches/0003)
pocket/translation/Metal/LegacyMetal.h translation/Metal/LegacyMetal.h add
# The Brighter Shores profile and its copy helper
pocket/profiles/brighter-shores/profile.json profiles/brighter-shores/profile.json add
pocket/profiles/brighter-shores/README.md profiles/brighter-shores/README.md add
pocket/profiles/brighter-shores/install.py profiles/brighter-shores/install.py add
# Brighter Pocket Companion (management/, built by tools/make_companion.sh): finds the game in Steam's libraries (used by pocket/patches/0021)
pocket/management/SteamLibrary.swift management/App/Core/SteamLibrary.swift add
# Its own updates (Sparkle) and What's New, with the release notes it carries (used by pocket/patches/0034)
pocket/management/Updater.swift management/App/Core/Updater.swift add
pocket/management/WhatsNew.swift management/App/Views/WhatsNew.swift add
pocket/management/Info.plist management/Info.plist add
pocket/management/CompanionTests.swift management/Tests/CompanionTests.swift add
CHANGELOG.md management/CHANGELOG.md add
# The layer's defaults for the platform's builds: the app's name, Brighter Pocket, and only its profile (read by pocket/patches/0022)
pocket/layer.env layer.env add
